	'messages:apihelp-query+revisions-example-first5-user' => 'pt:Obter as primeiras 5 revisões da página [[{{MediaWiki:Mainpage}}]] feitas pelo utilizador <kbd>MediaWiki default</kbd>.',
	'messages:apihelp-query+revisions+base-param-prop' => 'pt:As propriedades a serem obtidas para cada revisão:',
